"studying":{a:[{tr:"i. (ders) çalışma, inceleme; öğrenim",ex:"Many students find that studying in short, focused sessions improves memory retention more than long sessions.",exTr:"Birçok öğrenci, kısa ve odaklanmış oturumlar hâlinde çalışmanın belleği uzun oturumlardan daha iyi pekiştirdiğini görüyor."}],kl:[{en:"worth studying",tr:"incelenmeye değer"},{en:"spend hours studying",tr:"saatlerce ders çalışmak"}]},
