"decreased":{a:[{tr:"s. azalmış, düşmüş",ex:"Researchers linked the decreased birth rate to rising living costs and changing social values.",exTr:"Araştırmacılar, azalan doğum oranını artan yaşam maliyetlerine ve değişen toplumsal değerlere bağladı."}],kl:[{en:"a decreased risk of sth",tr:"bir şeyin azalmış riski"},{en:"decreased demand",tr:"azalan talep"}]},
"discrete":{a:[{tr:"s. ayrık, kesikli; ayrı",ex:"Digital computers store information as discrete units rather than as continuous signals.",exTr:"Dijital bilgisayarlar, bilgiyi sürekli sinyaller yerine ayrık birimler hâlinde depolar."}],kl:[{en:"discrete units",tr:"ayrık birimler"},{en:"divided into discrete parts",tr:"ayrı parçalara bölünmüş"}]},
"equality":{a:[{tr:"i. eşitlik",ex:"The constitution guarantees equality before the law for all citizens regardless of origin.",exTr:"Anayasa, kökenine bakılmaksızın tüm vatandaşlar için yasa önünde eşitliği güvence altına alır."}],kl:[{en:"gender equality",tr:"toplumsal cinsiyet eşitliği"},{en:"equality of opportunity",tr:"fırsat eşitliği"},{en:"fight for equality",tr:"eşitlik için mücadele etmek"}]},
"excess":{a:[{tr:"i. fazlalık, aşırılık",ex:"Doctors warned that an excess of vitamin A can be just as harmful as a deficiency.",exTr:"Doktorlar, A vitamini fazlalığının tıpkı eksikliği kadar zararlı olabileceği konusunda uyardı.",yz:4},{tr:"s. fazla, aşırı",ex:"The body stores excess calories as fat, which may lead to serious health problems.",exTr:"Vücut, fazla kalorileri yağ olarak depolar; bu da ciddi sağlık sorunlarına yol açabilir.",yz:3}],kl:[{en:"in excess of sth",tr:"bir şeyi aşan, bir şeyin üzerinde"},{en:"an excess of sth",tr:"bir şeyin fazlası"},{en:"excess weight",tr:"fazla kilo"}]},
"hotel":{a:[{tr:"i. otel",ex:"The coastal town built a large hotel to accommodate the growing number of tourists.",exTr:"Kıyı kasabası, artan turist sayısını ağırlamak için büyük bir otel inşa etti."}],kl:[{en:"stay at a hotel",tr:"otelde kalmak"}]},
"hydrogen":{a:[{tr:"i. hidrojen",ex:"Many carmakers see hydrogen as a promising clean fuel for the vehicles of the future.",exTr:"Birçok otomobil üreticisi, hidrojeni geleceğin araçları için umut vadeden temiz bir yakıt olarak görüyor."}]},
