"leather":{a:[{tr:"i. (işlenmiş) deri",ex:"The factory exports leather goods such as bags and jackets to European markets.",exTr:"Fabrika; çanta ve ceket gibi deri ürünleri Avrupa pazarlarına ihraç ediyor.",yz:4},{tr:"s. deriden yapılma",ex:"He wore a brown leather jacket that had belonged to his grandfather during the war.",exTr:"Savaş sırasında büyükbabasına ait olan kahverengi bir deri ceket giyiyordu.",yz:2}],kl:[{en:"a leather jacket",tr:"deri ceket"},{en:"genuine leather",tr:"hakiki deri"}]},
"literally":{a:[{tr:"z. kelimenin tam anlamıyla; harfi harfine",ex:"During the heatwave, some roads literally melted under temperatures exceeding fifty degrees Celsius.",exTr:"Sıcak hava dalgası sırasında bazı yollar, elli dereceyi aşan sıcaklıklar altında kelimenin tam anlamıyla eridi."}],kl:[{en:"take sth literally",tr:"bir şeyi kelimesi kelimesine almak"},{en:"literally means",tr:"kelime anlamıyla demek"}]},
"mixture":{a:[{tr:"i. karışım, harman",ex:"The vaccine contains a mixture of proteins designed to trigger a strong immune response.",exTr:"Aşı, güçlü bir bağışıklık tepkisini tetiklemek üzere tasarlanmış bir protein karışımı içerir."}],kl:[{en:"a mixture of sth",tr:"bir şeylerin karışımı"},{en:"a strange mixture",tr:"tuhaf bir karışım"}]},
"neighbour":{a:[{tr:"i. komşu",ex:"A good neighbour can provide crucial support for elderly people living alone.",exTr:"İyi bir komşu, yalnız yaşayan yaşlılar için hayati bir destek sağlayabilir.",yz:4},{tr:"f. bitişik olmak, sınırı olmak",ex:"The small village neighbours a dense forest that attracts hikers throughout the year.",exTr:"Küçük köy, yıl boyunca yürüyüşçüleri cezbeden yoğun bir ormana bitişiktir.",yz:1}],kl:[{en:"a next-door neighbour",tr:"kapı komşusu"}]},
"obesity":{a:[{tr:"i. obezite, aşırı şişmanlık",ex:"Childhood obesity has tripled in many countries since fast food became widely available.",exTr:"Hazır yiyeceklerin yaygınlaşmasından bu yana birçok ülkede çocukluk çağı obezitesi üç katına çıktı."}],kl:[{en:"childhood obesity",tr:"çocukluk çağı obezitesi"},{en:"tackle obesity",tr:"obeziteyle mücadele etmek"}]},
"payment":{a:[{tr:"i. ödeme",ex:"Mobile applications now allow instant payment for goods without cash or physical cards.",exTr:"Mobil uygulamalar artık nakit veya fiziksel kart olmadan ürünler için anında ödeme yapılmasını sağlıyor."}],kl:[{en:"make a payment",tr:"ödeme yapmak"},{en:"payment for sth",tr:"bir şeyin karşılığında ödeme"},{en:"a monthly payment",tr:"aylık taksit"}]},
