"life-time":{a:[{tr:"i. ömür, yaşam süresi",ex:"During her lifetime, Marie Curie received two Nobel Prizes for her groundbreaking scientific discoveries.",exTr:"Marie Curie, yaşamı boyunca çığır açan bilimsel keşifleri nedeniyle iki Nobel Ödülü aldı."}],kl:[{en:"once in a lifetime",tr:"ömürde bir kez, hayatta bir defa"},{en:"during his lifetime",tr:"yaşamı boyunca, sağlığında"}]},
"marine":{a:[{tr:"s. denizel, denizle ilgili",ex:"Plastic pollution poses a severe threat to marine life throughout the world's oceans.",exTr:"Plastik kirliliği, dünya okyanuslarındaki deniz yaşamı için ciddi bir tehdit oluşturuyor.",yz:4},{tr:"i. deniz piyadesi (asker)",ex:"The young marine completed months of rigorous training before being deployed overseas.",exTr:"Genç deniz piyadesi, denizaşırı bir göreve gönderilmeden önce aylarca süren zorlu bir eğitimi tamamladı.",yz:1}],kl:[{en:"marine life",tr:"deniz canlıları"},{en:"marine pollution",tr:"deniz kirliliği"}]},
"offspring":{a:[{tr:"i. yavru; çocuk, döl",ex:"Many bird species feed their offspring for weeks until the young can fly independently.",exTr:"Birçok kuş türü, yavruları bağımsız uçabilir hale gelene kadar onları haftalarca besler."}],kl:[{en:"produce offspring",tr:"yavru vermek, üremek"},{en:"care for their offspring",tr:"yavrularına bakmak"}]},
"one-way":{a:[{tr:"s. tek yönlü",ex:"Early settlers regarded emigration as a one-way journey from which few ever returned.",exTr:"İlk yerleşimciler göçü, pek az kişinin geri döndüğü tek yönlü bir yolculuk olarak görüyordu."}],kl:[{en:"a one-way street",tr:"tek yönlü yol"},{en:"a one-way ticket",tr:"tek yön bilet, gidiş bileti"}]},
"penalty":{a:[{tr:"i. ceza, yaptırım",ex:"Companies that violate environmental regulations face a heavy penalty under the new legislation.",exTr:"Çevre düzenlemelerini ihlal eden şirketler, yeni yasa kapsamında ağır cezayla karşı karşıya kalıyor.",yz:4},{tr:"i. penaltı (futbolda)",ex:"The referee awarded a penalty after the defender fouled the striker inside the box.",exTr:"Hakem, defans oyuncusunun forveti ceza sahası içinde faullemesinin ardından penaltı verdi.",yz:1}],kl:[{en:"a penalty for sth",tr:"bir şeyin cezası"},{en:"impose a penalty",tr:"ceza vermek, yaptırım uygulamak"},{en:"the death penalty",tr:"idam cezası"}]},
"potato":{a:[{tr:"i. patates",ex:"The potato became a staple crop in Europe after its introduction from South America.",exTr:"Patates, Güney Amerika'dan getirilmesinin ardından Avrupa'da temel bir tarım ürünü haline geldi."}]},
